const allXmls = $input.all().map(item => item.json.data || '').filter(x => x.length > 0);
const seenLinks = new Set();
const allItems = [];

function urlHashFn(s) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 2654435761);
    h2 = Math.imul(h2 ^ c, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h1 >>> 0).toString(16).padStart(8,'0') + (h2 >>> 0).toString(16).slice(0,4);
}

for (const xml of allXmls) {
  const itemRegex = /<item>([\s\S]*?)<\/item>/g;
  let match;
  while ((match = itemRegex.exec(xml)) !== null) {
    const itemXml = match[1];
    const getTag = (tag) => {
      const r = new RegExp('<' + tag + '[^>]*>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\\/' + tag + '>');
      const m = itemXml.match(r);
      return m ? m[1].trim() : '';
    };
    const link = getTag('link');
    if (!link || seenLinks.has(link)) continue;
    seenLinks.add(link);
    const pubDateStr = getTag('pubDate');
    const pubDateMs = pubDateStr ? new Date(pubDateStr).getTime() : 0;
    const urlHash = 'h_' + urlHashFn(link);
    allItems.push({ title: getTag('title'), link, description: getTag('description'), pubDate: pubDateStr, pubDateMs, urlHash });
  }
}

allItems.sort((a, b) => b.pubDateMs - a.pubDateMs);
return [{ json: { articles: allItems.slice(0, 50).map(({ pubDateMs, ...rest }) => rest) } }];

const articles = $('Parse Articles').first().json.articles;
const sshOutput = $('Check Processed URLs').first().json.stdout || '';
const lines = sshOutput.split('\n').map(l => l.trim()).filter(l => l.length > 0);

// Parse hash and optional title slug (new format: "hash|title_slug", old format: "hash")
const processedHashes = new Set();
const processedSlugs = [];
for (const line of lines) {
  const pipe = line.indexOf('|');
  if (pipe === -1) {
    processedHashes.add(line);
  } else {
    processedHashes.add(line.slice(0, pipe));
    processedSlugs.push(line.slice(pipe + 1).toLowerCase());
  }
}

// Extract CVE numbers from text
const extractCVEs = (s) => ((s || '').match(/CVE-\d{4}-\d+/gi) || []).map(c => c.toUpperCase());
const processedCVEs = new Set(processedSlugs.flatMap(s => extractCVEs(s.replace(/_/g, ' '))));

// Stop words for title overlap check
const STOP = new Set(['about','after','alert','also','attack','attacks','based','been','being','could','data','exploit','exploited','exploiting','flaw','flaws','found','have','into','more','most','researchers','security','software','system','that','their','them','then','there','this','threat','used','using','vulnerability','vulnerabilities','what','when','which','with']);

const sigWords = (s) => new Set(
  s.toLowerCase().replace(/_/g, ' ').split(/\W+/).filter(w => w.length > 4 && !STOP.has(w))
);

const isTopicDuplicate = (article) => {
  const text = (article.title || '') + ' ' + (article.description || '');
  // CVE match — most reliable signal
  const cves = extractCVEs(text);
  if (cves.length > 0 && cves.some(c => processedCVEs.has(c))) return true;
  // Title word overlap — 3+ significant words in common with any processed title
  const aWords = sigWords(article.title || '');
  for (const slug of processedSlugs) {
    const sWords = sigWords(slug);
    let matches = 0;
    for (const w of aWords) { if (sWords.has(w)) matches++; }
    if (matches >= 3) return true;
  }
  return false;
};

let overrideTopic = '';
try { overrideTopic = ($('Check Override Topic').first().json.stdout || '').trim(); } catch(e) {}
let selected = null;

if (overrideTopic && overrideTopic.length > 3 && overrideTopic !== 'OVERRIDE_CLEARED') {
  const kw = overrideTopic.toLowerCase().split(/\s+/);
  for (const a of articles) {
    const t = (a.title || '').toLowerCase();
    const d = (a.description || '').toLowerCase();
    const hits = kw.filter(k => k.length > 3 && (t.includes(k) || d.includes(k))).length;
    if (hits >= 2 || t.includes(overrideTopic.toLowerCase())) { selected = { ...a, overrideUsed: true }; break; }
  }
}

if (!selected) {
  for (const a of articles) {
    if (!processedHashes.has(a.urlHash) && !isTopicDuplicate(a)) { selected = a; break; }
  }
}

if (!selected) {
  // All recent articles processed — pick randomly for variety
  const idx = Math.floor(Math.random() * articles.length);
  selected = { ...articles[idx], reused: true };
}

return [{ json: selected }];

const item = $('Select Unprocessed Article').first().json;
const htmlResponse = $input.first().json;

const title = item.title || '';
const link  = item.link  || '';

const stripHtml = (h) => {
  if (!h) return '';
  return h
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi,  '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<')
    .replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'")
    .replace(/\s+/g, ' ').trim();
};

const extractText = (html) => {
  if (!html || html.length < 300) return '';
  // 1. <article> tag
  const art = html.match(/<article[^>]*>([\s\S]{200,}?)<\/article>/i);
  if (art) { const t = stripHtml(art[1]); if (t.length > 300) return t; }
  // 2. Common content containers
  const containers = [
    /<div[^>]*class="[^"]*(?:article-body|post-content|entry-content|article-content|story-body|bc-cms-article|bc_post)[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /<div[^>]*id="[^"]*(?:article-body|post-content|entry-content|articleBody)[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /<main[^>]*>([\s\S]*?)<\/main>/i
  ];
  for (const re of containers) {
    const m = html.match(re);
    if (m) { const t = stripHtml(m[1]); if (t.length > 300) return t; }
  }
  // 3. All <p> tags
  const paras = [];
  const pRe = /<p[^>]*>([\s\S]*?)<\/p>/gi;
  let m;
  while ((m = pRe.exec(html)) !== null) {
    const t = stripHtml(m[1]);
    if (t.length > 40) paras.push(t);
  }
  if (paras.length >= 3) return paras.join(' ');
  return '';
};

const description = stripHtml(item.description || '');
let fullText = '';

const html = (htmlResponse && !htmlResponse.error) ? (htmlResponse.data || '') : '';
if (html.length > 500) {
  const extracted = extractText(html);
  if (extracted.length > 300) {
    fullText = (title + '. ' + extracted).slice(0, 4000).trim();
  }
}

if (fullText.length < 150) {
  fullText = title + '. ' + description;
}

if (fullText.length < 30) throw new Error('Article too short: ' + fullText.length + ' chars');

return [{ json: { title, link, description, fullText, urlHash: item.urlHash, overrideUsed: item.overrideUsed || false } }];

const articleTitle = $('Build Script Prompt').first().json.articleTitle;
const articleLink = $('Build Script Prompt').first().json.articleLink;
const data = $input.first().json;
if (!data.choices || !data.choices[0]) throw new Error('Groq returned no choices: ' + JSON.stringify(data).slice(0,300));

function parseGroqResponse(rawText, fallbackTitle) {
  rawText = rawText.replace(/```json/gi,'').replace(/```/g,'').replace(/\r/g,' ').replace(/\n/g,' ').replace(/\t/g,' ').replace(/\s+/g,' ').trim();
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  let result = null;
  if (jsonMatch) {
    try { result = JSON.parse(jsonMatch[0]); } catch(e) {
      try { result = JSON.parse(jsonMatch[0].replace(/([{,]\s*)(\w+)\s*:/g,'$1"$2":').replace(/:\s*'([^']*)'/g,': "$1"')); } catch(e2) { result = null; }
    }
  }
  if (!result) { result = { title: fallbackTitle, script: rawText, thumbnail_text: 'BREAKING NEWS', hashtags: '#cybersecurity #hacking #infosec #tech #shorts #cyberattack #databreach #security #hack #news', search_keywords: 'cybersecurity hacking technology', music_mood: 'dark' }; }
  result.title = String(result.title || fallbackTitle).trim();
  result.script = String(result.script || '').trim();
  result.thumbnail_text = String(result.thumbnail_text || 'BREAKING NEWS').trim();
  result.hashtags = String(result.hashtags || '#cybersecurity #hacking #infosec').trim();
  result.search_keywords = String(result.search_keywords || 'cybersecurity hacking').trim();
  result.music_mood = String(result.music_mood || 'dark').trim();
  result.thumbnailScene = String(result.thumbnailScene || 'cybersecurity concept dark dramatic lighting server room').trim();
  return result;
}

function countSentences(script) {
  // Split on sentence-ending punctuation followed by whitespace only
  // Avoids counting periods inside file extensions (clfs.sys) or abbreviations
  return script.split(/(?<=[.!?])\s+/).map(s => s.trim()).filter(Boolean).length;
}

let rawText = (data.choices[0].message.content || '').trim();
let result = parseGroqResponse(rawText, articleTitle);
let script = result.script.replace(/\s+/g,' ').trim();
let words = script.toLowerCase().split(/\s+/).filter(Boolean);
let sentences = countSentences(script);
let retried = false;

const WORD_MIN = 140;
const SENT_TARGET = 12;

if (words.length < WORD_MIN) {
  try {
    const retryBody = JSON.stringify({
      model: 'llama-3.3-70b-versatile',
      temperature: 0.7,
      max_tokens: 900,
      top_p: 0.85,
      frequency_penalty: 1.5,
      presence_penalty: 0.6,
      messages: [{
        role: 'user',
        content: 'Your previous script was ' + words.length + ' words and ' + sentences + ' sentences. Target is 150-170 words and exactly 12 sentences.\n\nHere is your script:\n\n' + script + '\n\nExpand every sentence under 12 words by adding one concrete named element: version, date, country, tool name, malware family, or victim org. Return ONLY the corrected JSON with the same fields (title, script, thumbnail_text, hashtags, search_keywords, music_mood).'
      }]
    });
    const retryResp = await fetch('https://api.groq.com/openai/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer YOUR_GROQ_API_KEY',
        'Content-Type': 'application/json',
        'User-Agent': 'Mozilla/5.0'
      },
      body: retryBody
    });
    if (retryResp.ok) {
      const retryData = await retryResp.json();
      if (retryData.choices && retryData.choices[0]) {
        const retryText = (retryData.choices[0].message.content || '').trim();
        const retryResult = parseGroqResponse(retryText, articleTitle);
        const retryScript = retryResult.script.replace(/\s+/g,' ').trim();
        const retryWords = retryScript.toLowerCase().split(/\s+/).filter(Boolean);
        if (retryWords.length > words.length) {
          result = retryResult;
          script = retryScript;
          words = retryWords;
          sentences = countSentences(script);
          retried = true;
        }
      }
    }
  } catch(retryErr) {
    // Retry failed silently -- use original result
  }
}

const issues = [];
if (words.length < 10) throw new Error('Groq returned empty or near-empty script (' + words.length + ' words). Check Groq API key, quota, and article content.');
if (words.length < WORD_MIN) issues.push('Too short: ' + words.length + ' words');
if (words.length > 220) issues.push('Too long: ' + words.length + ' words');
if (sentences !== SENT_TARGET) issues.push('Sentence count: ' + sentences + ' (target 12)');

const scriptSafe = script.replace(/[\\`$]/g,'').replace(/[^\x20-\x7E\n]/g,'').trim();
const titleSafe = result.title.replace(/[\\`$]/g,'').replace(/[^\x20-\x7E]/g,'').trim();
const hashtagsSafe = result.hashtags.replace(/[\\`$]/g,'').replace(/[^\x20-\x7E#]/g,'').trim();
const thumbnailSafe = result.thumbnail_text.toUpperCase().replace(/[\\`$]/g,'').replace(/[^\x20-\x7E]/g,'').trim();
const scriptB64 = Buffer.from(script).toString('base64');
const thumbnailB64 = Buffer.from(thumbnailSafe).toString('base64');
const hashtagsFirst3B64 = Buffer.from(hashtagsSafe.split(' ').slice(0,3).join(' ')).toString('base64');
const thumbnailSceneB64 = Buffer.from(result.thumbnailScene.replace(/[\\`$]/g,'').slice(0,200)).toString('base64');

return [{ json: { title: result.title, script, thumbnail_text: result.thumbnail_text, hashtags: result.hashtags, search_keywords: result.search_keywords, music_mood: result.music_mood, scriptSafe, scriptB64, titleSafe, hashtagsSafe, thumbnailSafe, thumbnailB64, hashtagsFirst3B64, thumbnailSceneB64, wordCount: words.length, sentenceCount: sentences, qualityIssues: issues.join('; '), retried, articleLink } }];

const data = $('Parse Script Response').first().json;
const wordCount = data.wordCount || 130;
let brollCount = Math.ceil(wordCount / 18);
brollCount = Math.max(6, Math.min(12, brollCount));

// Tech-category keyword pools for Pexels — mood-matched for visual consistency
// These always land in Pexels' technology/digital category
const techKeywordPools = {
  dark:       ['hacker dark', 'server room dark', 'binary code dark', 'cyber attack screen', 'dark keyboard computer'],
  tense:      ['server data center', 'network security monitor', 'code terminal dark', 'hacker screen', 'technology dark room'],
  dramatic:   ['data center server', 'hacker typing', 'digital security network', 'server cables glowing', 'computer screen code'],
  mysterious: ['digital matrix code', 'encrypted data stream', 'dark server room', 'binary data green', 'network infrastructure'],
  energetic:  ['technology network fast', 'server rack lights', 'data visualization tech', 'coding screen', 'hacker computer dark'],
  cinematic:  ['server room cinematic', 'data center wide shot', 'futuristic technology', 'dark computer room', 'network technology']
};

const mood = (data.music_mood || 'dark').toLowerCase().trim();
const pool = techKeywordPools[mood] || techKeywordPools['dark'];
const techKeyword = pool[Math.floor(Math.random() * pool.length)];

// groq_keywords preserved for debugging; search_keywords overwritten for Pexels
return [{ json: { ...data, broll_count: brollCount, groq_keywords: data.search_keywords, search_keywords: techKeyword, broll_keywords: techKeyword } }];

const stdout = $input.first().json.stdout || '';
const exitCode = $input.first().json.exitCode;
if (stdout.includes('VALIDATION_FAILED')) {
  const msg = (stdout.match(/VALIDATION_FAILED: (.+)/) || [])[1] || 'Voice validation failed';
  throw new Error(msg);
}
if (exitCode !== 0 && exitCode != null) throw new Error('SSH failed (exit ' + exitCode + '): ' + stdout.slice(0,200));
if (!stdout.includes('VALIDATION_PASSED')) throw new Error('Unexpected validation output: ' + stdout.slice(0,200));
return [{ json: $input.first().json }];

const ttsOut = $('Generate Voice and Subtitles').first().json.stdout || '';
const scriptData = $('Parse Script Response').first().json;
const tsMatch = ttsOut.match(/TIMESTAMP=(\d+)/);
if (!tsMatch) throw new Error('No timestamp in TTS output: ' + ttsOut.slice(0,200));
if (!ttsOut.includes('TTS_DONE')) throw new Error('TTS did not complete: ' + ttsOut.slice(0,200));
if (ttsOut.includes('ERROR:') && !ttsOut.includes('WARN:')) {
  const err = (ttsOut.match(/ERROR:.*/) || [])[0] || 'unknown';
  throw new Error('TTS error: ' + err);
}
return [{ json: { ...scriptData, timestamp: tsMatch[1] } }];

const data = $input.first().json;
const ts = $('Extract Timestamp').first().json.timestamp;
const allVideos = data.videos || [];
if (allVideos.length === 0) {
  console.log('WARN: No Pexels videos returned — will use synthetic background');
  return [{ json: { downloadCmds: '', concatList: '', timestamp: ts, clipCount: 0, totalClipDuration: 0, targetDuration: 0, useStaticBg: true } }];
}

// How much footage we need: 2x estimated voice duration (safety buffer), max 180s
const wordCount = $('Parse Script Response').first().json.wordCount || 130;
const voiceSecs = wordCount / 2.5;
const targetSecs = Math.min(voiceSecs * 2.0, 180);

const pexelsCdnPattern = /^https:\/\/[a-zA-Z0-9.\-]+\.pexels\.com\//;
const shuffled = allVideos.sort(() => Math.random() - 0.5);
const clips = [];
let totalDuration = 0;

for (const v of shuffled) {
  if (clips.length >= 25) break;                    // hard cap
  if (totalDuration >= targetSecs) break;            // stop once we have enough
  const file = (v.video_files || []).filter(f => f.height >= 720).sort((a,b) => a.width - b.width)[0]
               || (v.video_files || [])[0];
  if (!file || !file.link) continue;
  if (!pexelsCdnPattern.test(file.link)) continue;
  const safeUrl = file.link.replace(/["'`$\\]/g, '');
  const clipDur = v.duration || 10;
  clips.push({ url: safeUrl, index: clips.length, duration: clipDur });
  totalDuration += clipDur;
}

if (clips.length < 2) {
  console.log('WARN: Not enough valid clips (' + clips.length + ') — will use synthetic background');
  return [{ json: { downloadCmds: '', concatList: '', timestamp: ts, clipCount: 0, totalClipDuration: 0, targetDuration: 0, useStaticBg: true } }];
}

const downloadCmds = clips.map(c => `echo "DL:${c.index}" && wget -q --timeout=20 --tries=2 "${c.url}" -O /tmp/clip${c.index}_${ts}.mp4 && echo "OK:${c.index}" || echo "FAIL:${c.index}"`).join('\n');
const concatList   = clips.map(c => `file '/tmp/clip${c.index}_${ts}.mp4'`).join('\n');

return [{ json: {
  downloadCmds, concatList, timestamp: ts,
  clipCount: clips.length,
  totalClipDuration: Math.round(totalDuration),
  targetDuration: Math.round(targetSecs)
} }];

const scriptData = $('Parse Script Response').first().json;
const dlData = $('Build Download Commands').first().json;
const catalogRaw = ($input.first().json.stdout || '').trim();

let catalog = [];
try { catalog = JSON.parse(catalogRaw); } catch(e) { catalog = []; }

let mood = (scriptData.music_mood || 'dark').toLowerCase().trim().split('|')[0].trim();
const t = (scriptData.title || '').toLowerCase();
if (/hack|breach|attack|exploit/.test(t))        mood = 'tense';
else if (/warn|alert|danger|critical/.test(t))   mood = 'dramatic';
else if (/spy|secret|hidden/.test(t))            mood = 'cinematic';
else if (/million|billion|steal|theft/.test(t))  mood = 'dramatic';
else if (/exposed|leaked|caught|banned/.test(t)) mood = 'tense';

// Prefer generated tracks matching mood; fall back to any generated; then static
const moodMatches = catalog.filter(e => e.mood === mood);
const pool = moodMatches.length > 0 ? moodMatches : catalog;

let musicFile;
if (pool.length > 0) {
  const pick = pool[Math.floor(Math.random() * pool.length)];
  musicFile = '/home/YOUR_USER/bgmusic/generated/' + pick.file;
  console.log('Using generated music:', pick.file, '(mood:', pick.mood + ')');
} else {
  // Static library fallback
  const moodMap = {
    dark:       ['dark1.mp3','dark2.mp3','dark3.mp3'],
    tense:      ['tense1.mp3','tense2.mp3','tense3.mp3'],
    dramatic:   ['dramatic1.mp3','dramatic2.mp3'],
    cinematic:  ['cinematic1.mp3'],
    energetic:  ['energetic1.mp3','energetic2.mp3'],
    mysterious: ['mysterious1.mp3']
  };
  const files = moodMap[mood] || moodMap['dark'];
  const pick = files[Math.floor(Math.random() * files.length)];
  musicFile = '/home/YOUR_USER/bgmusic/' + pick;
  console.log('Fallback to static music:', pick);
}

return [{
  json: {
    ...scriptData,
    downloadCmds: dlData.downloadCmds,
    concatList:   dlData.concatList,
    clipCount:    dlData.clipCount,
    timestamp:    dlData.timestamp,
    musicFile,
    musicMood: mood
  }
}];

