echo "SIZE=$SIZE DURATION=${DINT}s VCODEC=$VID ACODEC=$AUD"

[ "$SIZE" -lt 1000000 ] && { echo "VALIDATION_FAILED: too small ($SIZE bytes)"; exit 1; }
[ "$DINT" -lt 30 ] && { echo "VALIDATION_FAILED: too short (${DINT}s)"; exit 1; }
[ -z "$VID" ] && { echo "VALIDATION_FAILED: no video stream"; exit 1; }
