const videoOut = $('Read Video as Base64').first().json.stdout || '';
const thumbOut = $('Read Thumbnail as Base64').first().json.stdout || '';
const videoB64 = videoOut.split('\n').filter(l => !l.startsWith('FATAL') && !l.startsWith('DEBUG') && l.trim().length > 100).join('').trim();
const thumbB64 = thumbOut.split('\n').filter(l => !l.startsWith('FATAL') && !l.startsWith('DEBUG') && l.trim().length > 100).join('').trim();
if (!videoB64 || videoB64.length < 10000) throw new Error('Video base64 too small or missing. Length: ' + videoB64.length);
