const sd = $('Parse Script Response').first().json;
const title = sd.title || 'Cybersecurity News';
const hashtags = sd.hashtags || '#cybersecurity #hacking #infosec';
const script = sd.script || '';
const description = script + '\n\n' + hashtags + '\n\n#Shorts #YouTubeShorts #CyberSecurity #Hacking #InfoSec';
const tags = hashtags.split(' ').filter(h => h.startsWith('#')).map(h => h.replace('#','')).concat(['shorts','cybersecurity','hacking','infosec']).slice(0,15);
return [{ json: { title, description, tags, categoryId: '28' }, binary: { video: { data: videoB64, mimeType: 'video/mp4', fileName: 'short.mp4' }, thumbnail: { data: thumbB64, mimeType: 'image/jpeg', fileName: 'thumb.jpg' } } }];

