const item = $input.first().json;
let script = item.script || '';

function rewriteForTTS(text) {
  // Flatten bullet points / numbered lists
  text = text.replace(/^\s*[-•*]\s+/gm, '').replace(/^\s*\d+\.\s+/gm, '');

  // Split into sentences
  let sentences = text.split(/(?<=[.!?])\s+/).map(s => s.trim()).filter(Boolean);

  // Break sentences >25 words at pivot conjunctions
  sentences = sentences.flatMap(s => {
    if (s.split(' ').length <= 25) return [s];
    const broken = s.replace(/,\s+(but|however|yet|while|though|although)\s+/gi, (m, c) =>
      '. ' + c.charAt(0).toUpperCase() + c.slice(1) + ' '
    );
    const parts = broken.split(/(?<=[.!?])\s+/).map(x => x.trim()).filter(Boolean);
    return parts.length > 1 ? parts : [s];
  });

  // Make first sentence punchy (split on first comma/colon if >12 words)
  if (sentences.length > 0 && sentences[0].split(' ').length > 12) {
    const m = sentences[0].match(/^(.{15,60}?)[,;:]\s+(.{10,}.*)$/);
    if (m) {
      const s1 = m[1].replace(/[,;:]$/, '') + '.';
      const s2 = m[2].charAt(0).toUpperCase() + m[2].slice(1);
      sentences.splice(0, 1, s1, s2);
    }
  }

  // Em-dashes on pivots
  sentences = sentences.map(s =>
    s.replace(/,\s+(but|however|yet|still)\s+/gi, ' — $1 ')
     .replace(/,\s+(including|such as)\s+/gi, ' — including ')
  );

  // Ellipses before dramatic stats (dollar amounts, large numbers)
  sentences = sentences.map(s =>
    s.replace(/:\s+(\$[\d,.]+|\d[\d,]*\s*(million|billion|thousand|percent|%))/gi, '... $1')
  );

  return sentences.join(' ');
}

function cleanForSubtitles(text) {
  text = text.replace(/\.\.\./g, '.');
  const pairs = [
    [/\bit is\b/g, "it's"], [/\bdo not\b/g, "don't"], [/\bcannot\b/g, "can't"],
    [/\bwill not\b/g, "won't"], [/\bdoes not\b/g, "doesn't"], [/\bwas not\b/g, "wasn't"],
    [/\bare not\b/g, "aren't"], [/\bthey are\b/g, "they're"], [/\bthat is\b/g, "that's"],
    [/\bhere is\b/g, "here's"], [/\bthere is\b/g, "there's"], [/\bwould not\b/g, "wouldn't"],
    [/\bcould not\b/g, "couldn't"], [/\bshould not\b/g, "shouldn't"],
    [/\bhe is\b/g, "he's"], [/\bshe is\b/g, "she's"], [/\bwe are\b/g, "we're"],
    [/\byou are\b/g, "you're"],
  ];
  for (const [pat, rep] of pairs) text = text.replace(pat, rep);
  return text;
}

const ttsScript     = rewriteForTTS(script);
const subtitleScript = cleanForSubtitles(ttsScript);
const ttsB64        = Buffer.from(ttsScript).toString('base64');
const subB64        = Buffer.from(subtitleScript).toString('base64');

return [{
  json: {
    ...item,
    script:            ttsScript,
    subtitleScript,
    scriptB64:         ttsB64,
    subtitleScriptB64: subB64,
    wordCount:         ttsScript.split(/\s+/).filter(Boolean).length,
    sentenceCount:     ttsScript.split(/(?<=[.!?])\s+/).map(s => s.trim()).filter(Boolean).length,
  }
}];

